-- =============================================================================
-- 03_data.sql
-- Small demonstration dataset for testing the website and spatial queries.
-- Coordinates are illustrative WGS 84 longitude/latitude values near Brno.
-- Habitat exterior rings are closed and ordered counter-clockwise.
-- =============================================================================

SET DEFINE OFF;

-- Animals (ANIMAL_ID values are generated by identity columns).
INSERT INTO animals (animal_name, scientific_name, description)
VALUES ('Red fox', 'Vulpes vulpes', 'A widespread mammal found in varied habitats.');

INSERT INTO animals (animal_name, scientific_name, description)
VALUES ('European hare', 'Lepus europaeus', 'A mammal commonly associated with open grassland.');

-- Habitat polygons. SDO_GTYPE 2003 = two-dimensional polygon.
INSERT INTO habitats (habitat_name, animal_id, geom)
SELECT
    'North woodland',
    a.animal_id,
    SDO_GEOMETRY(
        2003,
        4326,
        NULL,
        SDO_ELEM_INFO_ARRAY(1, 1003, 1),
        SDO_ORDINATE_ARRAY(
            16.6000, 49.1900,
            16.6200, 49.1900,
            16.6200, 49.2050,
            16.6000, 49.2050,
            16.6000, 49.1900
        )
    )
FROM animals a
WHERE a.animal_name = 'Red fox';

INSERT INTO habitats (habitat_name, animal_id, geom)
SELECT
    'Eastern grassland',
    a.animal_id,
    SDO_GEOMETRY(
        2003,
        4326,
        NULL,
        SDO_ELEM_INFO_ARRAY(1, 1003, 1),
        SDO_ORDINATE_ARRAY(
            16.6250, 49.1850,
            16.6450, 49.1850,
            16.6450, 49.2000,
            16.6250, 49.2000,
            16.6250, 49.1850
        )
    )
FROM animals a
WHERE a.animal_name = 'European hare';

-- Sightings. SDO_GTYPE 2001 = two-dimensional point.
-- Image fields are omitted in this demo; the website can upload a BLOB later.
INSERT INTO sightings (animal_id, sighted_at, notes, geom)
SELECT
    a.animal_id,
    TIMESTAMP '2026-10-20 09:15:00',
    'Observed near the woodland edge.',
    SDO_GEOMETRY(2001, 4326, SDO_POINT_TYPE(16.6100, 49.1980, NULL), NULL, NULL)
FROM animals a
WHERE a.animal_name = 'Red fox';

INSERT INTO sightings (animal_id, sighted_at, notes, geom)
SELECT
    a.animal_id,
    TIMESTAMP '2026-10-21 16:40:00',
    'Observed in open grassland.',
    SDO_GEOMETRY(2001, 4326, SDO_POINT_TYPE(16.6350, 49.1920, NULL), NULL, NULL)
FROM animals a
WHERE a.animal_name = 'European hare';

INSERT INTO sightings (animal_id, sighted_at, notes, geom)
SELECT
    a.animal_id,
    TIMESTAMP '2026-10-22 07:30:00',
    'Second observation near the woodland edge.',
    SDO_GEOMETRY(2001, 4326, SDO_POINT_TYPE(16.6150, 49.2010, NULL), NULL, NULL)
FROM animals a
WHERE a.animal_name = 'Red fox';

COMMIT;

-- ---------------------------------------------------------------------------
-- Geometry validation. The block fails loudly if any geometry is invalid.
-- VALIDATE_GEOMETRY_WITH_CONTEXT returns 'TRUE' for valid geometry or a
-- diagnostic string describing the problem.
-- ---------------------------------------------------------------------------
DECLARE
    v_invalid_count NUMBER;
BEGIN
    SELECT COUNT(*)
    INTO v_invalid_count
    FROM habitats h
    WHERE SDO_GEOM.VALIDATE_GEOMETRY_WITH_CONTEXT(h.geom, 0.05) <> 'TRUE';

    IF v_invalid_count > 0 THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            'Geometry validation failed for ' || v_invalid_count || ' habitat(s).'
        );
    END IF;

    SELECT COUNT(*)
    INTO v_invalid_count
    FROM sightings s
    WHERE SDO_GEOM.VALIDATE_GEOMETRY_WITH_CONTEXT(s.geom, 0.05) <> 'TRUE';

    IF v_invalid_count > 0 THEN
        RAISE_APPLICATION_ERROR(
            -20002,
            'Geometry validation failed for ' || v_invalid_count || ' sighting(s).'
        );
    END IF;
END;
/

-- Display the validation result for evidence in the project report.
SELECT habitat_id,
       habitat_name,
       SDO_GEOM.VALIDATE_GEOMETRY_WITH_CONTEXT(geom, 0.05) AS validation_result
FROM habitats
ORDER BY habitat_id;

SELECT sighting_id,
       SDO_GEOM.VALIDATE_GEOMETRY_WITH_CONTEXT(geom, 0.05) AS validation_result
FROM sightings
ORDER BY sighting_id;
